/*
 * trace_gsplat_hip.h — HIP kernel source (compiled at runtime by hiprtc) for
 * LightRT 3D Gaussian splat chunks. Direct port of vk/shaders/trace_gsplat.comp
 * (which mirrors gs_trace_chunk in lightrt_c_gsplat.c). Kernel math ported from
 * Blender 5.3 Cycles (Apache-2.0, Blender Foundation).
 *
 * SPDX-License-Identifier: Apache-2.0
 */
#ifndef LIGHTRT_TRACE_GSPLAT_HIP_H
#define LIGHTRT_TRACE_GSPLAT_HIP_H

static const char *const k_lrt_hip_trace_gsplat_src =
    "#define NO_HIT 0xFFFFFFFFu\n"
    "#define GS_STACK 64\n"
    "struct gs_node { float lo[3], hi[3]; unsigned int first, count; };\n"
    "struct gs_splat { float mu[3]; float opacity; float a[9]; float radius;\n"
    "                  unsigned int id, pad; };\n"
    "__device__ static float gs_hash(const float p[3], unsigned int seed) {\n"
    "  unsigned int h = 0x9e3779b9u ^ (seed * 0x85ebca6bu);\n"
    "  for (int i = 0; i < 3; ++i) {\n"
    "    unsigned int b = __float_as_uint(p[i]);\n"
    "    h ^= b + 0x7f4a7c15u + (h << 6) + (h >> 2);\n"
    "    h = h * 747796405u + 2891336453u;\n"
    "    h = ((h >> ((h >> 28u) + 4u)) ^ h) * 277803737u;\n"
    "    h = (h >> 22u) ^ h;\n"
    "  }\n"
    "  return (float)(h >> 8) * (1.f / 16777216.f);\n"
    "}\n"
    "__device__ static bool gs_box(const gs_node &nd, const float o[3],\n"
    "                              const float inv[3], float tmin, float tmax,\n"
    "                              float *tnear) {\n"
    "  float t0 = tmin, t1 = tmax;\n"
    "  for (int k = 0; k < 3; ++k) {\n"
    "    float a = (nd.lo[k] - o[k]) * inv[k], b = (nd.hi[k] - o[k]) * inv[k];\n"
    "    t0 = fmaxf(t0, fminf(a, b));\n"
    "    t1 = fminf(t1, fmaxf(a, b));\n"
    "  }\n"
    "  *tnear = t0;\n"
    "  return t0 <= t1;\n"
    "}\n"
    "extern \"C\" __global__ void lrt_hip_trace_gsplat(\n"
    "    const gs_node *__restrict__ nodes, const gs_splat *__restrict__ splats,\n"
    "    const float *__restrict__ rays, unsigned int *__restrict__ hits,\n"
    "    unsigned int ray_count, unsigned int seed_base, unsigned int node_count) {\n"
    "  unsigned int gid = blockIdx.x * blockDim.x + threadIdx.x;\n"
    "  if (gid >= ray_count) return;\n"
    "  const float *r = rays + gid * 8u;\n"
    "  const float o[3] = {r[0], r[1], r[2]}, d[3] = {r[4], r[5], r[6]};\n"
    "  const float tmin = r[3];\n"
    "  float best = r[7];\n"
    "  const unsigned int seed = seed_base + gid;\n"
    "  float inv[3];\n"
    "  for (int k = 0; k < 3; ++k) {\n"
    "    float v = 1.f / d[k];\n"
    "    if (!(v >= -1e18f && v <= 1e18f)) v = (d[k] < 0.f) ? -1e18f : 1e18f;\n"
    "    inv[k] = v;\n"
    "  }\n"
    "  const float dd = d[0] * d[0] + d[1] * d[1] + d[2] * d[2];\n"
    "  unsigned int best_id = NO_HIT;\n"
    "  float best_alpha = 0.f;\n"
    "  unsigned int stk[GS_STACK];\n"
    "  int sp = 0;\n"
    "  float tn;\n"
    "  if (node_count > 0u && gs_box(nodes[0], o, inv, tmin, best, &tn)) stk[sp++] = 0u;\n"
    "  while (sp > 0) {\n"
    "    const gs_node nd = nodes[stk[--sp]];\n"
    "    if (nd.count == 0u) {\n"
    "      float ta, tb;\n"
    "      bool ha = gs_box(nodes[nd.first], o, inv, tmin, best, &ta);\n"
    "      bool hb = gs_box(nodes[nd.first + 1u], o, inv, tmin, best, &tb);\n"
    "      if (ha && hb && sp + 2 <= GS_STACK) {\n"
    "        if (ta <= tb) { stk[sp++] = nd.first + 1u; stk[sp++] = nd.first; }\n"
    "        else { stk[sp++] = nd.first; stk[sp++] = nd.first + 1u; }\n"
    "      } else if (ha && sp < GS_STACK) {\n"
    "        stk[sp++] = nd.first;\n"
    "      } else if (hb && sp < GS_STACK) {\n"
    "        stk[sp++] = nd.first + 1u;\n"
    "      }\n"
    "      continue;\n"
    "    }\n"
    "    for (unsigned int i = nd.first; i < nd.first + nd.count; ++i) {\n"
    "      const gs_splat &g = splats[i];\n"
    "      const float oc[3] = {o[0] - g.mu[0], o[1] - g.mu[1], o[2] - g.mu[2]};\n"
    "      const float b = oc[0] * d[0] + oc[1] * d[1] + oc[2] * d[2];\n"
    "      const float c = oc[0] * oc[0] + oc[1] * oc[1] + oc[2] * oc[2] -\n"
    "                      g.radius * g.radius;\n"
    "      if (b * b - dd * c < 0.f) continue;\n"
    "      const float *A = g.a;\n"
    "      const float og[3] = {A[0] * oc[0] + A[1] * oc[1] + A[2] * oc[2],\n"
    "                           A[3] * oc[0] + A[4] * oc[1] + A[5] * oc[2],\n"
    "                           A[6] * oc[0] + A[7] * oc[1] + A[8] * oc[2]};\n"
    "      const float dg[3] = {A[0] * d[0] + A[1] * d[1] + A[2] * d[2],\n"
    "                           A[3] * d[0] + A[4] * d[1] + A[5] * d[2],\n"
    "                           A[6] * d[0] + A[7] * d[1] + A[8] * d[2]};\n"
    "      const float t = -(og[0] * dg[0] + og[1] * dg[1] + og[2] * dg[2]) /\n"
    "                      (dg[0] * dg[0] + dg[1] * dg[1] + dg[2] * dg[2]);\n"
    "      if (!(t >= tmin && t <= best)) continue;\n"
    "      const float e0 = og[0] + dg[0] * t, e1 = og[1] + dg[1] * t,\n"
    "                  e2 = og[2] + dg[2] * t;\n"
    "      const float alpha = g.opacity * expf(-0.5f * (e0 * e0 + e1 * e1 + e2 * e2));\n"
    "      const float x[3] = {o[0] + d[0] * t, o[1] + d[1] * t, o[2] + d[2] * t};\n"
    "      if (gs_hash(x, seed) > alpha) continue;\n"
    "      best = t;\n"
    "      best_alpha = alpha;\n"
    "      best_id = g.id;\n"
    "    }\n"
    "  }\n"
    "  unsigned int *h = hits + gid * 4u;\n"
    "  h[0] = __float_as_uint(best_id != NO_HIT ? best : 0.f);\n"
    "  h[1] = __float_as_uint(best_alpha);\n"
    "  h[2] = 0u;\n"
    "  h[3] = best_id;\n"
    "}\n";

#endif /* LIGHTRT_TRACE_GSPLAT_HIP_H */
